from mojoanalyzer.core import RISKS
from mojoanalyzer.rules import ALL

out = [
    "# Rules",
    "",
    "Generated by `scripts/gen_rules_doc.py`. `mojoanalyzer --explain RULE` prints the same text.",
    "",
]
out += ["| id | name | severity | confidence | risk |", "|---|---|---|---|---|"]
out += [f"| [{r.id}](#{r.id.lower()}) | {r.name} | {r.severity} | {r.confidence} | {r.risk} |" for r in ALL]
for r in ALL:
    out += [
        "",
        f"## {r.id}",
        "",
        f"`{r.name}` severity={r.severity} confidence={r.confidence} risk={r.risk} ({RISKS[r.risk]})",
        "",
    ]
    out += [" ".join((r.__doc__ or "").split())]
    if r.why:
        out += ["", f"Why: {r.why}"]
    out += ["", "Bad:", "", "```mojo", r.bad.strip("\n"), "```", "", "Good:", "", "```mojo", r.good.strip("\n"), "```"]
print("\n".join(out))
